describe('listing sessions', () => {
  const loggedErrors = captureErrors();

  it('answers list_sessions with ISO-dated summaries for session.userId, empty when listFor is absent, and SERVER_ERROR logged under ws when it throws', async () => {
    const before = {updatedAt: '2026-01-01T00:05:00.000Z', sessionId: 's3'};
    const recordedCalls: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const listed = await sendListSessions(
      {type: 'list_sessions', limit: 10, before, userId: 'u2'},
      {
        listFor: (userId, options) => {
          recordedCalls.push({userId, options});
          return [
            {
              sessionId: 's2',
              createdAt: new Date('2026-01-01T00:00:00.000Z'),
              updatedAt: new Date('2026-01-01T00:02:00.000Z'),
              entryCount: 4,
            },
          ];
        },
      } as unknown as SessionStore
    );
    const absent = await sendListSessions({type: 'list_sessions'}, {} as SessionStore);
    const omitted = await sendListSessions({type: 'list_sessions'});
    const failed = await sendListSessions(
      {type: 'list_sessions'},
      {listFor: () => Promise.reject(new Error('database offline'))} as unknown as SessionStore
    );

    expect({recordedCalls, listed, absent, omitted, failed, loggedErrors}).toEqual({
      recordedCalls: [{userId: 'u1', options: {limit: 10, before}}],
      listed: [
        {
          type: 'session_list',
          sessions: [
            {
              sessionId: 's2',
              createdAt: '2026-01-01T00:00:00.000Z',
              updatedAt: '2026-01-01T00:02:00.000Z',
              entryCount: 4,
            },
          ],
        },
      ],
      absent: [{type: 'session_list', sessions: []}],
      omitted: [{type: 'session_list', sessions: []}],
      failed: [{type: 'error', code: 'SERVER_ERROR', message: 'Failed to list sessions'}],
      loggedErrors: [{category: 'ws', message: expect.any(String), userId: 'u1', error: 'database offline'}],
    });
  });
});

async function sendListSessions(frame: unknown, sessionStore?: SessionStore): Promise<OutgoingMessage[]> {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const orchestrator = {} as ChatOrchestrator;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  await createMessageHandler(orchestrator, sessionStore)(ws, session, frame);
  return sent;
}

